tabs.code:
.page {
  display: flex;
}

.filters {
  width: 0; /* geometry: layout on every frame */
  overflow: hidden;
  transition: width 300ms ease-out;
}

.filters.open {
  width: 280px;
}

.grid {
  flex: 1; /* re-wraps while the panel grows */
}

.filters {
  position: fixed;
  inset: 0 auto 0 0;
  width: 280px; /* laid out once */
  transform: translateX(-100%);
  transition: transform 300ms ease-out;
}

.filters.open {
  transform: none; /* composite only */
}
